export function custoDistribuidor(produto, estado, desconto) {
  const uf = String(estado || "SP").toUpperCase();
  const desc = String(Number(desconto) || 42);
  const tabela = produto?.custos || {};
  const faixa = tabela[uf] || tabela.SP || {};
  const valor = faixa[desc] ?? faixa["42"] ?? produto?.preco ?? 0;
  return Number(valor) || 0;
}

export function custoComDesconto(preco, desconto, produto, estado) {
  if (produto) return custoDistribuidor(produto, estado, desconto);
  return Number(preco) || 0;
}

export function buscarProdutos(termo) {
  const t = (termo || "").trim().toLowerCase();
  if (t.length < 2) return [];
  return PRODUTOS.filter((p) =>
    p.nome.toLowerCase().includes(t) || (p.detalhe || "").toLowerCase().includes(t)
  ).slice(0, 12);
}

export function produtoPorId(id) {
  return PRODUTOS.find((p) => p.id === id) || null;
}

export function produtoPorNome(nome) {
  const t = String(nome || "").toLowerCase();
  return PRODUTOS.find((p) => p.nome.toLowerCase() === t) || null;
}
